 const event=race.events[0];if(event.text!==lastEvent){lastEvent=event.text;eventAt=performance.now();$('#log').textContent=`${event.time.toFixed(1)}s · ${event.text}`;$('#eventBanner').textContent=event.text;beep();}$('#eventBanner').classList.toggle('visible',race.status==='running'&&performance.now()-eventAt<4000);
