function reset(){race.reset();demo=false;uiLast='';renderUI();}
function choose(id,route){if(race.status==='ready')race.chooseOpening(id,route);else race.chooseFinal(id,route);renderUI();}
function attack(id){if(!race.attack(id)){ $('#log').textContent='暂无安全的合法落点，卡牌未消耗。';}renderUI();}
function toggleFloor(){document.body.classList.toggle('floor');}
$('#startBtn').onclick=()=>{race.start();renderUI();};$('#demoBtn').onclick=()=>{reset();demo=true;race.chooseOpening(0,'beacon');race.chooseOpening(1,'outer');race.start();renderUI();};$('#resetBtn').onclick=reset;$('#pauseBtn').onclick=()=>{race.paused=!race.paused;renderUI();};$('#floorBtn').onclick=()=>{toggleFloor();};canvas.ondblclick=()=>document.body.classList.remove('floor');$('#helpBtn').onclick=()=>$('#help').showModal();$('#closeHelp').onclick=$('#gotIt').onclick=()=>$('#help').close();$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent='声音：'+(sound?'开':'关');$('#soundBtn').setAttribute('aria-pressed',String(sound));beep();};
document.addEventListener('click',e=>{const r=e.target.closest('[data-route]'),a=e.target.closest('[data-attack]');if(r&&!r.disabled)choose(+r.dataset.player,r.dataset.route);if(a&&!a.disabled)attack(+a.dataset.attack);if(e.target.closest('[data-reset]'))reset();});
document.addEventListener('keydown',e=>{if(e.repeat||$('#help').open||['INPUT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase(),options=race.quake!==null?['risk','safe']:['beacon','outer'];if(['1','2'].includes(k))choose(0,options[+k-1]);if(['8','9'].includes(k))choose(1,options[+k-8]);if(k==='q')attack(0);if(k==='p')attack(1);if(k===' '&&race.status==='running'){e.preventDefault();race.paused=!race.paused;renderUI();}if(k==='f')toggleFloor();if(k==='escape')document.body.classList.remove('floor');});
let broadcastAt=0;function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;if(!floor){if(demo&&race.status==='running'&&!race.paused){if(race.time>9&&race.players[1].card)race.attack(1);if(race.quake!==null&&!race.locked&&race.time-race.quake>2){race.chooseFinal(0,'risk');race.chooseFinal(1,'safe');}if(race.locked&&race.time-race.quake>4&&race.players[0].card)race.attack(0);}race.step(dt*simulationScale);if(channel&&now-broadcastAt>60){channel.postMessage({type:'state',state:JSON.parse(JSON.stringify(race))});broadcastAt=now;}}render();renderUI();requestAnimationFrame(frame);}renderUI();requestAnimationFrame(frame);
