window.lunar={snapshot:()=>JSON.parse(JSON.stringify(race)),getRouteTimings:()=>({beacon:42,outer:48,safe:20,risk:(ROUTES.riskIn.length+ROUTES.riskRock.length+ROUTES.source.length+ROUTES.stable.length)/SPEED,collapse:(ROUTES.riskIn.length+ROUTES.riskRock.length+ROUTES.source.length+ROUTES.collapse.length)/SPEED})};
